/* ============================================================
   أطياب الجاسم — مشهد المبخرة الثلاثي الأبعاد (ثلاثية + نموذج GLB مُدمج)
   مصدرها: الوحدة (module) داخل الحزمة الجاهزة (standalone) كما هي،
   تعتمد على window.mabkharaConfig (src/home/mabkhara-config.js) وعلى
   العناصر: #mabkharaRoot #mabkharaCanvas #mabkharaLoader #mabkharaError
             #mabkharaRetry #mabkharaHint — كلها في index.html.
   يُحمَّل عند الطلب فقط (lazy) من src/home.js عند دخول مسار #home.
   السياسة الأصلية للكرت getWebGLPowerPreference() محفوظة كما هي:
   سطح المكتب "default" — الهاتف "low-power".
   ============================================================ */

/**
 * WebGL power policy:
 * - Desktop/laptop: `default` = balanced GPU selection (there is no literal "medium" value in WebGL).
 * - Phones: `low-power` = prefer the power-efficient GPU/context.
 * This keeps the scene suitable for embedding in React or any other Web App.
 */
function getWebGLPowerPreference() {
  const ua = navigator.userAgent || "";
  const isPhoneUA = /Android.*Mobile|iPhone|iPod|Windows Phone/i.test(ua);
  const isPhoneUAData = navigator.userAgentData && navigator.userAgentData.mobile === true;
  return isPhoneUA || isPhoneUAData ? "low-power" : "default";
}

/* =====================================================================================
   مبخرة ثلاثية الأبعاد — تهيئة المسرح (stage).
   يستورد src/bakhoor/scene.js الذي يقلع تلقائيًا عند تحميله، ثم يوصل الأشياء التي تخصّ
   الصفحة المستضيفة وحدها:
     • شاشة التحميل حتى أول إطار مرسوم      → الحدث mabkhara:ready
     • لوحة الخطأ مع زر إعادة المحاولة      → الحدث mabkhara:error
     • إيقاف/تشغيل حلقة الرسم لما يخرج القسم عن الشاشة (توفير بطارية)
   ملفات المشهد: scene.js / environment.js / coal.js / fire.js / fall.js / particles.js
   والمجسم المضغوط: models/mabkhara.glb  (مبني من مسح «البخور الثلاثي» الأصلي)
   ===================================================================================== */

const root = document.getElementById("mabkharaRoot");
const loader = document.getElementById("mabkharaLoader");
const errorPanel = document.getElementById("mabkharaError");
const retryBtn = document.getElementById("mabkharaRetry");
const hintEl = document.getElementById("mabkharaHint");

if (root) {
  let ready = false;
  let watchdogId = 0;

  /** The scene is a WebGL canvas; without WebGL there is nothing to wait for, so
   *  fail immediately with a readable reason instead of an endless spinner. */
  function hasWebGL() {
    try {
      const probe = document.createElement("canvas");
      return !!(window.WebGLRenderingContext && (probe.getContext("webgl2") || probe.getContext("webgl")));
    } catch (error) {
      return false;
    }
  }

  function markReady() {
    if (ready) return;
    ready = true;
    if (watchdogId) { window.clearTimeout(watchdogId); watchdogId = 0; }
    root.classList.add("is-ready");
    if (loader) loader.setAttribute("hidden", "");
    refresh();
    if (hintEl) {
      hintEl.classList.add("is-visible");
      window.setTimeout(() => hintEl.classList.remove("is-visible"), 6000);
      root.addEventListener("pointerdown", () => hintEl.classList.remove("is-visible"), { once: true });
    }
  }

  function markFailed(error) {
    if (ready) return;
    if (watchdogId) { window.clearTimeout(watchdogId); watchdogId = 0; }
    root.classList.add("is-failed");
    if (loader) loader.setAttribute("hidden", "");
    if (errorPanel) {
      errorPanel.removeAttribute("hidden");
      const detail = errorPanel.querySelector(".mabkhara-error-detail");
      if (detail) detail.textContent = error && error.message ? String(error.message).slice(0, 160) : "";
    }
  }

  window.addEventListener("mabkhara:ready", markReady);
  window.addEventListener("mabkhara:error", (event) => markFailed(event.detail));

  function setRunning(on) {
    const api = window.mabkhara;
    if (!api || typeof api.setRunning !== "function") return;
    try { api.setRunning(!!on); } catch (error) { /* المشهد لم يجهز بعد */ }
  }

  /* حالة التشغيل تُحسَب من الهندسة عند كل نداء — لا من عَلَم يبقى قديماً.
   * كان الاعتماد على آخر تقرير لـIntersectionObserver يُبقي المشهد متوقّفاً
   * إذا سجّل «خارج الشاشة» مرة ولم يصل تقرير جديد بعد عودة القسم إلى الشاشة
   * (تُحمّل المبخرة أول مرة ثم لا تعمل عند العودة). */
  function onScreenNow() {
    if (!root) return false;
    const rect = root.getBoundingClientRect();
    const h = window.innerHeight || 800;
    return rect.width > 0 && rect.height > 0 && rect.top < h + 160 && rect.bottom > -160;
  }

  let onScreen = true;
  function refresh() {
    const hiddenRoute = !!root.closest("[hidden]");
    onScreen = onScreenNow();
    setRunning(onScreen && !hiddenRoute);
  }

  if ("IntersectionObserver" in window) {
    new IntersectionObserver(() => refresh(), { rootMargin: "160px" }).observe(root);
  }
  window.addEventListener("scroll", refresh, { passive: true, capture: true });
  window.addEventListener("resize", refresh, { passive: true });
  document.addEventListener("atyab:route", () => window.setTimeout(refresh, 60));
  document.addEventListener("visibilitychange", refresh);

  if (retryBtn) {
    retryBtn.addEventListener("click", () => {
      if (errorPanel) errorPanel.setAttribute("hidden", "");
      root.classList.remove("is-failed");
      if (loader) loader.removeAttribute("hidden");
      const existing = document.getElementById("mabkharaCanvas");
      if (existing) existing.replaceWith(existing.cloneNode(false));
      const api = window.mabkhara;
      if (api) {
        try { api.setRunning(false); api.renderer.dispose(); } catch (error) {}
      }
      window.mabkhara = null;
      window.__mabkharaReady = false;
      window.__mabkharaError = null;
      const tag = document.getElementById("mabkharaBundle");
      const src = tag ? tag.textContent : "";
      if (!src) { window.location.reload(); return; }
      const url = URL.createObjectURL(new Blob([src], { type: "text/javascript" }));
      import(url).catch((error) => { console.error("[mabkhara] retry failed", error); markFailed(error); })
        .finally(() => { URL.revokeObjectURL(url); });
    });
  }

  async function run() {
    if (!hasWebGL()) {
      markFailed(new Error("المتصفّح لا يدعم العرض ثلاثي الأبعاد (WebGL)"));
      return;
    }
    if (watchdogId) window.clearTimeout(watchdogId);
    watchdogId = window.setTimeout(() => {
      markFailed(new Error("انتهت مدة انتظار المشهد — أعد المحاولة"));
    }, 30000);
    try {
      await Promise.resolve().then(function () { return scene; });
    } catch (error) {
      console.error("[mabkhara] import failed", error);
      markFailed(error);
    }
  }

  run();
}

